import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0011: 为什么 P0 只实现 Process 和 Exec Probe","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0011-why-p0-only-process-exec-probes.md","filePath":"zh/adr/ADR-0011-why-p0-only-process-exec-probes.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0011-why-p0-only-process-exec-probes.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0011-为什么-p0-只实现-process-和-exec-probe" tabindex="-1">ADR-0011: 为什么 P0 只实现 Process 和 Exec Probe <a class="header-anchor" href="#adr-0011-为什么-p0-只实现-process-和-exec-probe" aria-label="Permalink to “ADR-0011: 为什么 P0 只实现 Process 和 Exec Probe”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/probe-survey.md §26.11，roadmap P0</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>探测类型可以无限多（调研 §26 列了 20+ 种），但 P0 要证明的是架构：探针 → 归一化 → 诊断 → 依赖检查 → 恢复 → 独立验证 → 持久化 → 审计这条闭环正确。摊开 20 种探针 只会让每种都缺测试、缺语义打磨。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>P0 只实现 Process（pid 文件 + 存活）与 Exec（受控命令 + 超时 + 输出上限）两种探针， 用它们打通全部闭环与验收；其余探测类型按调研 §26.11 的建议顺序逐个补齐， <strong>每个带独立测试、跨平台语义（Linux/Windows）与归一化规则</strong>（连接拒绝≠超时、 Unreachable≠Unhealthy），补齐一项 tick 一项。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>一次实现全部探测类型</strong>：面铺开、深度不足；归一化规则没有逐类打磨， 误报/漏报在真实部署才暴露。</li><li><strong>只做 Exec 万能探针</strong>：丢失归一化（命令输出不是结构化健康状态）， 无法支撑验证与依赖条件。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：闭环质量先行；每类探针有独立语义边界与测试（现在 13 项高优全部完成， 145/145 绿）；后续扩展模板清晰。 缺点：早期可监控对象少（用户需用 Exec 兜底）。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>probe-survey §26.11 顺序成为补齐路线图；每类探针一个模块（icmp.rs/database.rs…）。</li><li>新探针必须同时给出：归一化规则、超时/权限语义、Windows 行为（cfg 或交叉检查）。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};